import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const r="/images/logic-studio/user-guide/blocks-js-en.png",m=JSON.parse('{"title":"Blocks JS","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/blocks-js.md","filePath":"en/projects/logic-studio/user-guide/blocks-js.md","lastUpdated":1794775908000}'),n={name:"en/projects/logic-studio/user-guide/blocks-js.md"};function i(l,e,d,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="blocks-js" tabindex="-1">Blocks JS <a class="header-anchor" href="#blocks-js" aria-label="Permalink to &quot;Blocks JS&quot;">​</a></h1><h2 id="first-example" tabindex="-1">First example <a class="header-anchor" href="#first-example" aria-label="Permalink to &quot;First example&quot;">​</a></h2><p>The test run reads a simulated entity state and writes it to the log.</p><ol><li>Choose <strong>New project → Blocks JS</strong>. Open <strong>System</strong> and drag <strong>Log</strong> into the workspace.</li><li>Drag <strong>State of</strong> from the same category into the open input on the log block. Select your test entity. The screenshot uses <code>binary_sensor.bewegung</code>.</li><li>Start a <strong>test run</strong> and open the <strong>Log</strong>. The demo shows the state and message <code>on</code>. This script only reads and logs the value.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-js-en.png"><img src="'+r+'" alt="Blocks JS with an entity state block and the resulting log"></a></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="system-actions-and-sendto" tabindex="-1">System, Actions and Sendto <a class="header-anchor" href="#system-actions-and-sendto" aria-label="Permalink to &quot;System, Actions and Sendto&quot;">​</a></h3><p>Read states, control approved targets, message scripts or query history. Dynamic inputs can use an entity ID from a loop.</p><h3 id="triggers-time-and-timeouts" tabindex="-1">Triggers, time and timeouts <a class="header-anchor" href="#triggers-time-and-timeouts" aria-label="Permalink to &quot;Triggers, time and timeouts&quot;">​</a></h3><p>Start on state changes, sun events or schedules. Use simple and named CRON jobs, delays, intervals and stop blocks.</p><h3 id="value-blocks" tabindex="-1">Value blocks <a class="header-anchor" href="#value-blocks" aria-label="Permalink to &quot;Value blocks&quot;">​</a></h3><p>Conversion, objects, logic, math, text, lists and colors produce values. Loops repeat operations.</p><h3 id="variables-and-functions" tabindex="-1">Variables and functions <a class="header-anchor" href="#variables-and-functions" aria-label="Permalink to &quot;Variables and functions&quot;">​</a></h3><p>Use variables for intermediate values and functions for reusable steps and return values.</p><h3 id="iobroker-import" tabindex="-1">ioBroker import <a class="header-anchor" href="#iobroker-import" aria-label="Permalink to &quot;ioBroker import&quot;">​</a></h3><p>In Expert mode, paste the export and check the report. Map entities explicitly and read each block&#39;s guidance.</p><h3 id="imported-http-blocks" tabindex="-1">Imported HTTP blocks <a class="header-anchor" href="#imported-http-blocks" aria-label="Permalink to &quot;Imported HTTP blocks&quot;">​</a></h3><p>Select an approved HA REST command for the URL, timeout and request headers. The imported POST Content-Type is shown in the block.</p><h3 id="test-run-and-play" tabindex="-1">Test run and Play <a class="header-anchor" href="#test-run-and-play" aria-label="Permalink to &quot;Test run and Play&quot;">​</a></h3><p>Use simulation first. Save before Play and check actual results in the log.</p><h2 id="check-an-import-step-by-step" tabindex="-1">Check an import step by step <a class="header-anchor" href="#check-an-import-step-by-step" aria-label="Permalink to &quot;Check an import step by step&quot;">​</a></h2><ol><li>Enable <strong>Expert mode</strong> in the project menu. In the editor, open <strong>Expert tools → Paste ioBroker export</strong>.</li><li>Paste Blockly XML or an ioBroker JavaScript export with embedded Blockly data. Check the import and read which blocks need a mapping.</li><li>Open the import as a project and resolve the guidance on the affected blocks. For example, select the HA REST command that defines the headers and timeout for an imported POST.</li><li>Save and start with a <strong>test run</strong>. Use <strong>Play</strong> for live execution, check the <strong>log</strong>, and press <strong>Stop</strong> when finished.</li></ol><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>Replace or adapt unsupported placeholders before running the script.</p>',24)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
